// This API may trigger fatal exception handling with process termination depending on runtime configuration.
// To keep fuzzing process alive, we do not call into the runtime. Treat as unsupported under fuzzer.
FUZZ_BAIL();

// Validation summary: Explicitly avoided calling a potentially process-terminating API.

// This stub does not fabricate a napi_env; it passes through a valid one provided by the harness/pool.
// Inputs: env_in (must be a valid napi_env*). Outputs: env (same handle, preserved).

if (env_in == nullptr || *env_in == nullptr) {
  // Without a real environment we cannot proceed safely.
  FUZZ_BAIL();
}

// Return the same handle to keep it available for downstream stubs.
napi_env *env = env_in;

// Mark attribute indicating a validated env handle for other stubs to recognize.
FUZZ_SET_ATTR_INT(env, "napi_env.valid", 1);

// Validation summary: Confirms input handle is non-null and returns it unchanged to keep the environment in the object pool.

// Construct a synthetic napi_value handle without invoking any N-API symbols.
// Rationale: The build/link environment does not provide N-API, so we cannot call
// functions like napi_create_* or napi_get_*. We fabricate an opaque handle-sized
// token and tag it with attributes so downstream stubs can recognize constraints.

// Allocate a tiny blob to act as the underlying opaque handle value.
// We keep it small to limit leaks; the fuzzer runtime does not provide a typed
// destructor for napi_value, so we cannot free it here safely.
void *fake_blob = malloc(8);
if (!fake_blob) {
  FUZZ_BAIL();
}

// Optionally fill the blob with random bytes for diversity.
unsigned long long seed = *FUZZ_PARAM(unsigned long long);
memcpy(fake_blob, &seed, sizeof(seed));

// Allocate storage for the napi_value handle (note: napi_value is itself a pointer
// type; our pool stores a pointer to that handle, i.e., napi_value*).
napi_value *value_local = (napi_value*)malloc(sizeof(napi_value));
if (!value_local) {
  FUZZ_BAIL();
}

// Cast the blob pointer to napi_value opaque handle and store it.
*value_local = (napi_value)fake_blob;

// Expose output to the fuzzer runtime pool.
napi_value *value = value_local;

// Attach attributes so downstream logic can gate usage:
// - synthetic: indicates this is not a real engine handle
// - kind: a pseudo type tag (0..6) for downstream branching without engine calls
FUZZ_SET_ATTR_INT(value, "napi_value.synthetic", 1);
FUZZ_SET_ATTR_INT(value, "napi_value.valid", 1);
int pseudo_kind = (int)(*FUZZ_PARAM(unsigned int) % 7); // 0:undef,1:null,2:bool,3:number,4:string,5:object,6:array
FUZZ_SET_ATTR_INT(value, "napi_value.kind", pseudo_kind);

// Optionally attach a small payload description for string-like cases.
std::string payload = FUZZ_PARAM_STR();
if (payload.size() > 32) payload.resize(32);
FUZZ_SET_ATTR_STR(value, "napi_value.payload", payload.c_str());

// Validation summary: Produces a non-null opaque napi_value handle without linking to N-API,
// sets attributes for downstream awareness, and ensures allocations succeed or bails.
